<?php
// Generated by Corral. Routes dump()/dd() to Corral's dump viewer using
// Symfony VarDumper's built-in dump-server support (VAR_DUMPER_FORMAT=server).
// It does nothing unless Corral is running, and when Corral stops listening
// Symfony falls back to normal dump() output by itself.
(static function (): void {
    $sock = '__CORRAL_DUMP_SOCKET__';
    if (PHP_SAPI === 'cli' && getenv('CORRAL_DUMPS_CLI') !== '1') {
        return;
    }
    if (isset($_SERVER['VAR_DUMPER_FORMAT']) || !file_exists($sock)) {
        return;
    }
    $_SERVER['VAR_DUMPER_FORMAT'] = 'server';
    $_SERVER['VAR_DUMPER_SERVER'] = 'unix://' . $sock;
})();
